-- SEO AI official plugin catalog. Legacy plugins remain for audit but are unpublished.
UPDATE plugins SET is_active = 0, status_label = 'legacy' WHERE plugin_slug NOT IN
('wordpress-connector','google-search-console','bing-indexnow','ai-content-brief','internal-link-pro','schema-graph-pro','geo-brand-radar','white-label-reports');

ON DUPLICATE KEY UPDATE plugin_name=VALUES(plugin_name),plugin_description=VALUES(plugin_description),plugin_version=VALUES(plugin_version),plugin_author=VALUES(plugin_author),plugin_path=VALUES(plugin_path),plugin_icon=VALUES(plugin_icon),plugin_category=VALUES(plugin_category),target_users=VALUES(target_users),credit_type=VALUES(credit_type),credit_amount=VALUES(credit_amount),is_installed=1,is_active=1,is_beta=VALUES(is_beta),status_label=VALUES(status_label),settings=VALUES(settings),updated_at=NOW();
